INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein dauerhafter Link immer statisch?', 2, '[{"text": "Ja", "correct": true, "because": "Permalinks ändern sich nicht"}, {"text": "Nein", "correct": false, "because": "Dynamische Links sind keine Permalinks"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptziel eines solchen Links?', 3, '[{"text": "Langfristige Zugänglichkeit", "correct": true, "because": "Sichert dauerhaften Zugriff"}, {"text": "Maximale Komplexität", "correct": false, "because": "Gegenteil des Ziels"}, {"text": "Manuelle Änderung", "correct": false, "because": "Soll stabil bleiben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale machen einen solchen Link effektiv?', 5, '[{"text": "Lesbarkeit", "correct": true, "because": "Fördert Verständnis"}, {"text": "Stabilität", "correct": true, "because": "Verhindert Broken Links"}, {"text": "Hohe Latenz", "correct": false, "because": "Eher ein Nachteil"}, {"text": "Temporäre Gültigkeit", "correct": false, "because": "Widerspricht Dauerhaftigkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Permalinks verbessern SEO. b) Sie ändern sich regelmäßig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) widerspricht Stabilität"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Erstellung eines dauerhaften Links?', 4, '[{"text": "URL-Struktur", "correct": false, "because": "Bestimmt Zugänglichkeit"}, {"text": "Klarheit", "correct": false, "because": "Fördert Nutzerfreundlichkeit"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant für Links"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein solcher Link immer eine Webseite adressiert?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch Dateien oder APIs adressieren"}, {"text": "Ja", "correct": false, "because": "Nicht auf Webseiten beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium ist für einen dauerhaften Link entscheidend?', 3, '[{"text": "Konsistenz", "correct": true, "because": "Verhindert 404-Fehler"}, {"text": "Hohe Komplexität", "correct": false, "because": "Erschwert Nutzung"}, {"text": "Manuelle Generierung", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein solcher Link?', 5, '[{"text": "SEO-Optimierung", "correct": true, "because": "Suchmaschinen bevorzugen stabile URLs"}, {"text": "Nutzerfreundlichkeit", "correct": true, "because": "Klar und merkfähig"}, {"text": "Temporäre Gültigkeit", "correct": false, "because": "Widerspricht Ziel"}, {"text": "Hohe Verschlüsselung", "correct": false, "because": "Nicht primär relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Solche Links sind für CMS typisch. b) Sie ändern sich bei Updates. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) widerspricht Stabilität"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen dauerhaften Link?', 4, '[{"text": "Stabile URL", "correct": false, "because": "Kern des Permalinks"}, {"text": "Lesbare Struktur", "correct": false, "because": "Fördert Verständnis"}, {"text": "3D-Rendering", "correct": true, "because": "Kein Linkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind solche Links nur für Blogs relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Foren, Shops, APIs"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Systeme nutzen solche Links häufig?', 4, '[{"text": "Content-Management-Systeme", "correct": true, "because": "Wie WordPress"}, {"text": "E-Commerce-Plattformen", "correct": true, "because": "Für Produktseiten"}, {"text": "Hardwaresteuerung", "correct": false, "because": "Andere Schnittstellen"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass solche Links immer kurz sein müssen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Länge sekundär, Stabilität primär"}, {"text": "Ja", "correct": false, "because": "Kürze nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Gestaltung eines dauerhaften Links?', 3, '[{"text": "Beschreibende URLs", "correct": true, "because": "Fördert Klarheit"}, {"text": "Zufällige Zeichen", "correct": false, "because": "Verwirren Nutzer"}, {"text": "Manuelle Änderungen", "correct": false, "because": "Stabilität wichtiger"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Permalinks vermeiden Broken Links. b) Sie benötigen immer Datenbanken.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es bei solchen Links?', 5, '[{"text": "URL-Änderungen", "correct": true, "because": "Brechen Stabilität"}, {"text": "Migrationen", "correct": true, "because": "Erfordern Redirects"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Linkproblem"}, {"text": "Bildbearbeitung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem dauerhaften Link unwichtig?', 3, '[{"text": "Stabilität", "correct": false, "because": "Kernmerkmal"}, {"text": "SEO-Freundlichkeit", "correct": false, "because": "Fördert Sichtbarkeit"}, {"text": "Musikwiedergabe", "correct": true, "because": "Kein Linkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Müssen solche Links verschlüsselt sein?', 3, '[{"text": "Nein", "correct": true, "because": "HTTPS separat, nicht zwingend"}, {"text": "Ja", "correct": false, "because": "Verschlüsselung optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob solche Links für APIs nützlich sind?', 2, '[{"text": "Ja", "correct": true, "because": "Stabile Endpunkte fördern Nutzung"}, {"text": "Nein", "correct": false, "because": "APIs profitieren davon"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einem dauerhaften Link?', 4, '[{"text": "Verlinkung eines Blogposts", "correct": true, "because": "Braucht stabile URL"}, {"text": "Musikwiedergabe", "correct": false, "because": "Andere Technologie"}, {"text": "Netzwerkkonfiguration", "correct": false, "because": "Technische Aufgabe"}]');
